                                ["fallback"] = "Don't talk to me like that.",
                                ["id"] = "guarded",
                                ["templateID"] = "convo.social.hostile_boundary.say.1.guarded",
                                ["textRole"] = "spoken_action",
                                ["translations"] = {
                                    ["EN"] = {
