                        },
                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_QuestionRelationshipStatusAfterComplimentCommitted",
                        ["text"] = {
                            ["EN"] = "Thanks for the compliment, but I thought we were already together.",
