                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_QuestionRelationshipStatusAfterComplimentWithdrawn",
                        ["text"] = {
                            ["EN"] = "Thanks, but I'd rather keep that personal.",
                            ["TL"] = "Salamat, pero mas gusto kong sarilinin muna iyan.",
