                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_SelfReflectionDefault",
                        ["text"] = {
                            ["EN"] = "Don't talk about yourself like that.",
                            ["TL"] = "Huwag mong pagsalitaan nang masama ang sarili mo.",
