                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_SelfReflectionFriendly",
                        ["text"] = {
                            ["EN"] = "Hey. Don't talk about yourself like that. You matter.",
                            ["TL"] = "Huwag mong pagsalitaan nang ganyan ang sarili mo. Mahalaga ka.",
                        },
                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_SelfReflectionStressed",
                        ["text"] = {
                            ["EN"] = "We've all made mistakes. Focus on what comes next.",
                            ["TL"] = "Lahat tayo ay nagkakamali. Ituon mo ang pansin sa susunod na hakbang.",
                        },
                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_SelfReflectionTrusted",
                        ["text"] = {
                            ["EN"] = "You're harder on yourself than you need to be.",
