                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_SelfReflectionWithdrawn",
                        ["text"] = {
                            ["EN"] = "Don't make a habit of saying things like that.",
                            ["TL"] = "Huwag mong gawing ugali ang pagsasabi ng ganyan.",
