                    },
                    {
                        ["key"] = "UI_PNC_Conversation_Semantic_SocialInteractionRejected",
                        ["text"] = {
                            ["EN"] = "I heard you, but I couldn't apply that social reaction.",
                            ["TL"] = "Narinig kita, pero hindi ko mailapat ang sosyal na reaksyon.",
